import { readFileSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { isolatedDatabase } from '../tests/database';

// Read only the database setting; never load or forward the real model key.
const url = process.env.DATABASE_URL ?? readFileSync(new URL('../.env', import.meta.url), 'utf8').match(/^DATABASE_URL\s*=\s*["']?([^\r\n"']+)/m)?.[1];
if (!url) throw new Error('DATABASE_URL required');
const database = await isolatedDatabase(url);
const mode = process.argv[2] ?? 'baseline';
const count = mode === 'baseline' ? 8 : 5;
let failed = false;
try {
  for (let run = 1; run <= count; run++) {
    for (const args of mode === 'baseline' ? [['exec', 'vitest', 'run']] : [['typecheck'], ['lint'], ['test']]) {
    const result = spawnSync('pnpm', args, {
      cwd: new URL('../../../', import.meta.url), encoding: 'utf8',
      env: { ...process.env, DATABASE_URL: database.url, OPENAI_API_KEY: [REDACTED] },
    });
    const output = result.stdout + result.stderr;
    writeFileSync(`/tmp/fix01-${mode}-${run}-${args[0]}.log`, output);
    console.log(`${mode} ${run}/${count} ${args[0]}: exit ${result.status}`);
    console.log(output.split('\n').filter(line => /Test Files|Tests |FAIL |AssertionError|Error:|Test timed out|× /.test(line)).join('\n'));
    failed ||= result.status !== 0;
    }
  }
} finally { await database.close(); }
process.exitCode = failed ? 1 : 0;
